  const bikeIdlePct = ov.bike.sockets > 0 ? Math.round((ov.bike.idle / ov.bike.sockets) * 100) : 0;
  const carIdlePct = ov.car.sockets > 0 ? Math.round((ov.car.idle / ov.car.sockets) * 100) : 0;
